SELECT w.id, 'M187-09-D1', 'h_FK_SS_calc = EBCT * v_filter_aufstrom / 60', ARRAY['EBCT','v_filter_aufstrom']::text[], 'h_FK_SS_calc', 'm', '§5.1.3.1 c)', 'Plan 3: Mindesthöhe des Filterkörpers der Sorptionsstufe aus Filterkontaktzeit und Filtergeschwindigkeit — EBCT [min] · v [m/h] / 60 = m; 15 min · 5,0 m/h = 1,25 m („Das entspricht einer Mindesthöhe des Filterkörpers von 1,25 m“). Das Eingabefeld h_FK_SS (VR ≥ 1.25) bleibt (m187-D-4); die Beziehung ist als Satz, nicht als Gleichung gedruckt (m187-F-3).', 'imported_unverified', 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-09' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
