SELECT w.id, 'M187-14-D1', 'V_segment_soll = Q_T_d_aM * 86.4', ARRAY['Q_T_d_aM']::text[], 'V_segment_soll', 'm³', '§5.2.3.1 c)', 'Plan 3: Retentionsvolumen je Segment = mittlerer täglicher Trockenwetterzufluss Q_T,d,aM · 1 d — Q_T,d,aM [l/s] · 86 400 s/d / 1000 l/m³ = · 86,4 m³/d. Die Umrechnung ist nicht gedruckt (m187-F-1).', 'imported_unverified', 'Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-14' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-14-D2', 'segmente_count = count_rows(filtersegmente)', ARRAY['filtersegmente']::text[], 'segmente_count', NULL, '§5.2.3.1 c)', 'Plan 3: Anzahl der hydraulisch entkoppelten Segmente; „muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden“ — Gate ≥ 2 STAGED (m187-G-9); drei Segmente sind Erfahrung (m187-J-3).', 'imported_unverified', 'Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-14' AND s.code = 'DWA-M-187'
