INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-16-D1', 'log_red_min = min_rows(indikatororganismen, log_red, ablauf > 0)', ARRAY['indikatororganismen']::text[], 'log_red_min', 'log', '§5.3.2, §5.3.3.1', 'Plan 3: kleinster Rückhalt (Log-Stufen = log10(Zulauf / Ablauf)) über die erfassten Indikatororganismen, Zeilen mit Ablauf > 0; Ziel > 1,0 Log-Stufe (> 90 %). Frachtbezogene Wirkungsgradermittlung (§5.3.4.3) ist nicht abgebildet (m187-F-2). Das Eingabefeld logstufen_rueckhalt bleibt (m187-D-7).', 'imported_unverified', 'Die Verringerung der Zulauffracht an Indikatororganismen wurde für RBF im Mischsystem umfassend großtechnisch untersucht und beträgt im Mittel $90 \%$ ( 1,0 Log-Stufe), wobei Schwankungen des Ereigniswirkungsgrads im Wesentlichen zwischen $0,5 \mathrm{Log}$-Stufen bis $1,5 \mathrm{Log}$-Stufen auftreten. In Einzelfällen wurden Rückhalte von bis zu 3,0 Log-Stufen nachgewiesen (WaldhoFF 2008). Für somatische Coliphagen ist der Rückhalt geringer mit Werten zwischen 0,5 Log-Stufen bis 1,0 Log-Stufen (Tondera et al. 2019). Die Effekte, welche diese Spannbreiten bedingen, werden in den Folgeabschnitten genannt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-16' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-16-D2', 'organismen_count = count_rows(indikatororganismen)', ARRAY['indikatororganismen']::text[], 'organismen_count', NULL, '§5.3.2', 'Plan 3: Anzahl der erfassten Indikatororganismen (vollständige Zeilen).', 'imported_unverified', 'Der Rückhalt von pathogenen Mikroorganismen in RBF wurde überwiegend für die Indikatororganismen E. coli und intestinale Enterokokken sowie für somatische Coliphagen untersucht. Die Zulaufbelastungen unterliegen in ihrer stofflichen Belastung starken Schwankungen, was auch für den Gehalt mit Indikatororganismen zutrifft. Diese sind zudem ortspezifisch.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-16' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-20-D1', 'A_F_gesamt = sum_rows(teilfilterbecken, flaeche_m2)', ARRAY['teilfilterbecken']::text[], 'A_F_gesamt', 'm²', '§5.4.3', 'Plan 3: Gesamtfilterfläche als Summe der Teilfilterbecken — Bezugsfläche der CSB-Fracht ≤ 20 g CSB/(m²·d) und der 750 m²/ha A_E,b.', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-20' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-20-D2', 'A_F_aktiv = sum_rows(teilfilterbecken, if(in_betrieb == true, flaeche_m2, 0))', ARRAY['teilfilterbecken']::text[], 'A_F_aktiv', 'm²', '§5.4.3', 'Plan 3: Filterfläche der in Betrieb befindlichen Teilfilterbecken („jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause“).', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-20' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-20-D3', 'teilfilter_count = count_rows(teilfilterbecken)', ARRAY['teilfilterbecken']::text[], 'teilfilter_count', NULL, '§5.4.3', 'Plan 3: Anzahl der Teilfilterbecken (vollständige Zeilen). Das Eingabefeld anzahl_teilfilter bleibt (m187-D-5).', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-20' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-20-D4', 'A_F_min_ohne_daten = lookup(''S5_4_3_ORG'', ''a_f_pro_aeb'', ''wert'') * A_E_b', ARRAY['A_E_b']::text[], 'A_F_min_ohne_daten', 'm²', '§5.4.3', 'Plan 3: Mindest-Gesamtfilterfläche ohne CSB-Frachtdaten = 750 m²/ha · A_E,b [ha] („Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens 750 m²/ha A_E,b betragen“). Gate A_F_gesamt ≥ A_F_min_ohne_daten (nur ohne Daten) STAGED (m187-G-2); das Produkt ist nicht als Gleichung gedruckt (m187-F-4).', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-20' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-20-D5', 'B_CSB_calc = CSB_fracht_d / A_F_gesamt', ARRAY['CSB_fracht_d','A_F_gesamt']::text[], 'B_CSB_calc', 'g/(m²·d)', '§5.4.3', 'Plan 3: CSB-Filterflächenbelastung = CSB-Fracht [g/d, Jahresdurchschnitt] / Gesamtfilterfläche [m²] („bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt“). Gate B_CSB_calc ≤ 20 (nur mit Daten) STAGED (m187-G-2); der Quotient ist nicht als Gleichung gedruckt (m187-F-4). Das Eingabefeld B_CSB bleibt (m187-C-5).', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-20' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-20-D6', 'teilfilter_rest = teilfilter_count - 4 * floor(teilfilter_count / 4)', ARRAY['teilfilter_count']::text[], 'teilfilter_rest', NULL, '§5.4.3', 'Plan 3: Rest der Teilfilterbecken-Anzahl modulo vier — 0 bedeutet „vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken“; Gate == 0 STAGED (m187-G-10).', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-20' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-22-D1', 'A_F_sum_klein = sum_rows(klein_rbf_elemente, a_f_m2)', ARRAY['klein_rbf_elemente']::text[], 'A_F_sum_klein', 'm²', '§5.5.4', 'Plan 3: Bodenfilteroberfläche aller Einzelelemente. Das Eingabefeld A_F (Gl. 1 = 0,01 · A_b_a · 10000) bleibt (m187-D-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-22' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-22-D2', 'A_b_a_sum_klein = sum_rows(klein_rbf_elemente, a_b_a_m2)', ARRAY['klein_rbf_elemente']::text[], 'A_b_a_sum_klein', 'm²', '§5.5.4, §5.5.2', 'Plan 3: angeschlossene befestigte Fläche aller Einzelelemente in m² (Anwendungsbereich A_b,a < 1 ha = 10 000 m², L859 — Gate STAGED m187-G-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-22' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-22-D3', 'elemente_unter_1m2 = count_rows(klein_rbf_elemente, a_f_ok == 0)', ARRAY['klein_rbf_elemente']::text[], 'elemente_unter_1m2', NULL, '§5.5.4', 'Plan 3: Einzelelemente mit A_F < 1,0 m² („sollte … nicht unterschritten werden“ — warn, STAGED m187-G-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-22' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-22-D4', 'A_F_anteil_calc = A_F_sum_klein * 100 / A_b_a_sum_klein', ARRAY['A_F_sum_klein','A_b_a_sum_klein']::text[], 'A_F_anteil_calc', '%', '§5.5.4', 'Plan 3: spezifische Bodenfilteroberfläche Σ A_F / Σ A_b,a in % — Regelwert 1,0 % (= 100 m²/ha); < 1,0 % mit b_krit-Nachweis nach Gl. 2 zulässig (REQ-06 erzwingt == 1.0, m187-G-6). Das Eingabefeld A_F_anteil_Aba bleibt (m187-D-6).', 'imported_unverified', 'Mit entsprechender Nachweisführung über die zufließende mittlere Jahreswassermenge und der prognostizierten mittleren AFS-Zulaufbelastung (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$ möglich.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-22' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-22-D5', 'h_FK_min_klein = if(carbonatschicht_vorhanden == ''ja'', lookup(''S5_LIMITS_APP'', ''klein_rbf'', ''h_fk_carbonat_m''), lookup(''S5_LIMITS_APP'', ''klein_rbf'', ''h_fk_min_m''))', ARRAY['carbonatschicht_vorhanden']::text[], 'h_FK_min_klein', 'm', '§5.5.3.2.2', 'Plan 3: Mindesthöhe des Filterkörpers Klein-RBF — 0,25 m (L926), mit Carbonatschicht h_FK,CaCO3 ≥ 0,10 m aus Carbonatbrechsand (80 % CaCO3) auf 0,2 m verringerbar (L930; kein Operator gedruckt, m187-J-4). carbonatschicht_vorhanden ist von M187-21 übergeben. Gate h_FK ≥ h_FK_min_klein STAGED (m187-G-1).', 'imported_unverified', 'Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-22' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M187-22-D6', 'elemente_count = count_rows(klein_rbf_elemente)', ARRAY['klein_rbf_elemente']::text[], 'elemente_count', NULL, '§5.5.4', 'Plan 3: Anzahl der Einzelelemente (vollständige Zeilen).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M187-22' AND s.code = 'DWA-M-187'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
COMMIT;
